/**
 * Top bar: the app's wordmark (upper-cased, second letter in the accent color) and a menu button
 * that turns into a cross while the menu page is open. Pass it as `Scaffold(topBar = …)`.
 * [actions] go just before the menu button (e.g. a notifications bell).
 *
 * With liquid glass on (and a wallpaper behind the screen), the bar is a full-width glass strip
 * driven by the same Apparence sliders as the cards — nothing overridden. Glass off with a
 * wallpaper shown: the cards' "+"-button blur without outline ([glassFabSurface], foundation
 * liquid-glass.md §5.4). Glass off, no wallpaper: no background.
 * [glass] = false when the caller already draws a glass surface around the bar (e.g. Donova's
 * header, which also holds the selection toolbar).
 */
@Composable
fun AppTopBar(
    name: String,
    menuOpen: Boolean,
    onMenuToggle: () -> Unit,
    modifier: Modifier = Modifier,
    glass: Boolean = true,
    actions: @Composable RowScope.() -> Unit = {},
) {
    val backdrop = LocalScreenBackdrop.current
    val glassOn = glass && AppTheme.liquidGlassEnabled && wallpaperBackdropActive && backdrop != null
    Box(modifier.fillMaxWidth()) {
        // Sibling layer, not a modifier on the Row: the bar's content stays out of the glass node.
        if (glassOn) Box(Modifier.matchParentSize().liquidGlassCard(backdrop = backdrop!!, topRadius = 0.dp, bottomRadius = 0.dp))
        else if (glass && wallpaperBackdropActive && backdrop != null) {
            Box(Modifier.matchParentSize().glassFabSurface(backdrop, RectangleShape, borderColor = Color.Transparent))
        }
        AppTopBarContent(name, menuOpen, onMenuToggle, actions)
    }
}

@Composable
private fun AppTopBarContent(
    name: String,
    menuOpen: Boolean,
    onMenuToggle: () -> Unit,
    actions: @Composable RowScope.() -> Unit,
) {
    val word = name.uppercase()
    Row(
        modifier = Modifier.fillMaxWidth().padding(horizontal = 16.dp, vertical = 8.dp),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.CenterVertically,
    ) {
        Text(
            buildAnnotatedString {
                withStyle(SpanStyle(color = TextPrimary)) { append(word.take(1)) }
                withStyle(SpanStyle(color = Accent)) { append(word.drop(1).take(1)) }
                withStyle(SpanStyle(color = TextPrimary)) { append(word.drop(2)) }
            },
            style = MaterialTheme.typography.headlineSmall.copy(fontWeight = FontWeight.Bold),
            modifier = Modifier.weight(1f),
        )
        actions()
        IconButton(onClick = onMenuToggle) {
            Icon(
                if (menuOpen) Icons.Filled.Close else Icons.Filled.Menu,
                contentDescription = if (menuOpen) "Fermer" else "Menu",
                tint = TextPrimary,
            )
        }
    }
}

/** One row of [GlassMenuPanel]. */
data class MenuEntry(
    val icon: ImageVector,
    val title: String,
    val subtitle: String,
    val onClick: () -> Unit,
)

/**
 * The menu, as a full page: it takes the whole content area (both bars stay) instead of a small
 * dropdown. Show it in place of the current tab while the menu is open. Picking an entry closes
 * the menu first, then runs the entry; Back closes it.
 */
@Composable
fun GlassMenuPanel(
    entries: List<MenuEntry>,
    onDismiss: () -> Unit,
    modifier: Modifier = Modifier,
) {
    BackHandler(onBack = onDismiss)
    Column(modifier.fillMaxSize().padding(16.dp)) {
        GlassCard(Modifier.fillMaxWidth()) {
            Column(Modifier.padding(horizontal = 16.dp, vertical = 4.dp)) {
                entries.forEachIndexed { index, entry ->
                    if (index > 0) HorizontalDivider(color = Border)
                    MenuRow(entry) {
                        onDismiss()
                        entry.onClick()
                    }
                }
            }
        }
    }
}

@Composable
private fun MenuRow(entry: MenuEntry, onClick: () -> Unit) {
    Row(
        Modifier.fillMaxWidth().clickable(onClick = onClick).padding(vertical = 16.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(16.dp),
    ) {
        Icon(entry.icon, contentDescription = null, tint = Accent)
        Column(Modifier.weight(1f)) {
            Text(entry.title, style = MaterialTheme.typography.titleMedium, color = TextPrimary)
            Text(entry.subtitle, style = MaterialTheme.typography.bodySmall, color = TextSecondary)
        }
        Icon(Icons.AutoMirrored.Filled.KeyboardArrowRight, contentDescription = null, tint = TextSecondary)
    }
}
